/**
 * Valida a faixa (422 `PARAMETER_OUT_OF_RANGE`), exige motivo, grava histórico e auditoria. Com `expectedUpdatedAt`, outra edição no meio devolve 409 `PARAMETER_CONFLICT` (recarregue). Validação cruzada do ETA (RN-02, BUG-022), também no `reset`: `entrega_max_min` menos `entrega_faixa_min` precisa cobrir `entrega_preparo_padrao_min` + `entrega_despacho_min` + 5 e `entrega_faixa_min` <= `entrega_max_min` / 4; senão 422 `PARAMETER_OUT_OF_RANGE` com a prévia do alcance no `detail` e em `reachKm` (km de alcance que o valor proposto daria). Piso legal de troca é fixo (422 `PARAMETER_LOCKED`). Permissão de admin: `parameters:write` (tabela em apps/api/src/platform/auth/permissions.ts).
 * @summary Alterar parâmetro
 */
export const UpdateParameterParams = zod.object({
  "key": zod.string().describe('Chave do parâmetro')
})

export const updateParameterBodyValueTwoMax = 40;

export const updateParameterBodyReasonMin = 5;
export const updateParameterBodyReasonMax = 300;



export const UpdateParameterBody = zod.object({
  "value": zod.union([zod.number(),zod.string().max(updateParameterBodyValueTwoMax)]),
  "reason": zod.string().min(updateParameterBodyReasonMin).max(updateParameterBodyReasonMax),
  "expectedUpdatedAt": zod.iso.datetime({"offset":true}).nullish().describe('Versão que o painel viu (`updatedAt` do parâmetro; null = nunca editado). Se outro admin alterou antes, 409 `PARAMETER_CONFLICT`. Omitido = sem controle de versão.')
})

export const UpdateParameterResponse = zod.object({
  "key": zod.string(),
  "value": zod.union([zod.number(),zod.string()]),
  "default": zod.union([zod.number(),zod.string()]),
  "type": zod.enum(['int', 'decimal', 'enum', 'window']),
  "min": zod.number().nullable(),
  "max": zod.number().nullable(),
  "values": zod.array(zod.string()).nullable(),
  "description": zod.string(),
  "ref": zod.string().describe('Origem da regra (HIP, WB, DEC)'),
  "legalFloor": zod.boolean().describe('Piso legal fixo (ninguém edita)'),
  "updatedAt": zod.iso.datetime({"offset":true}).nullable()
})


